begin;
alter table public.scan_runs drop constraint scan_runs_status_check;
alter table public.scan_runs add constraint scan_runs_status_check check(status in ('running','completed','partial','failed','cancelled'));

create function public.save_query_result(result_payload jsonb) returns void
language plpgsql security invoker set search_path = public as $$
declare sid uuid := (result_payload->>'scanId')::uuid;
begin
  perform 1 from public.scan_runs where id = sid for update;
  if not found then raise exception 'Scan not found'; end if;
  insert into public.query_results(id,restaurant_id,scan_id,query_id,payload)
  values ((result_payload->>'id')::uuid,result_payload->>'restaurantId',sid,result_payload->>'queryId',result_payload)
  on conflict(scan_id,query_id) do nothing;
  update public.scan_runs set payload = payload || jsonb_build_object(
    'completedCount',(select count(*) from public.query_results where scan_id=sid),
    'successCount',(select count(*) from public.query_results where scan_id=sid and payload->>'status'='success')) where id=sid;
end;
$$;
create function public.cancel_scan(scan_id uuid) returns void
language plpgsql security invoker set search_path = public as $$
begin
  update public.scan_runs set payload=payload || '{"cancelRequested":true}'::jsonb where id=scan_id and status='running';
end;
$$;
create or replace function public.finish_scan(scan_payload jsonb, result_payloads jsonb, recommendation_payloads jsonb) returns void
language plpgsql security invoker set search_path = public as $$
declare item jsonb; current_payload jsonb;
begin
  select payload into current_payload from public.scan_runs where id=(scan_payload->>'id')::uuid for update;
  if not found then raise exception 'Scan not found'; end if;
  if current_payload->>'cancelRequested' = 'true' then
    scan_payload := scan_payload || '{"status":"cancelled","cancelRequested":true}'::jsonb;
  end if;
  update public.scan_runs set status=scan_payload->>'status',payload=scan_payload where id=(scan_payload->>'id')::uuid;
  for item in select value from jsonb_array_elements(result_payloads) loop
    perform public.save_query_result(item);
  end loop;
  for item in select value from jsonb_array_elements(recommendation_payloads) loop
    insert into public.recommendations(id,restaurant_id,payload) values(item->>'id',item->>'restaurantId',item)
    on conflict(id) do update set payload=excluded.payload || jsonb_build_object('status',recommendations.payload->>'status');
  end loop;
end;
$$;
revoke all on function public.save_query_result(jsonb),public.cancel_scan(uuid) from public,anon,authenticated;
grant execute on function public.save_query_result(jsonb),public.cancel_scan(uuid) to service_role;
